import type { LifecycleDefinition } from './lifecycle-definition-model';
import type { Workspace } from './workspace-model';

export const LifecycleStageStatusKeyToLabel = {
  'Active': 'Active',
  'Inactive': 'Inactive'
} as const;
export type LifecycleStageStatusKey = keyof typeof LifecycleStageStatusKeyToLabel;

export interface LifecycleStage {
  /**
   * @displayName Lifecycle Stage ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Stage Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  stageName: string;
  /**
   * @displayName Lifecycle Definition ID
   * @validationRule Required for create/update operations
   */
  lifecycleDefinitionID: Pick<LifecycleDefinition, 'id' | 'name1'>;
  /**
   * @displayName Sort Order
   * @validationRule Required for create/update operations
   */
  sortOrder: number;
  /**
   * @displayName Stage Code
   * @validationRule Required for create/update operations
   */
  stageCode: string;
  /**
   * @displayName Status
   * @validationRule Required for create/update operations
   */
  statusKey: LifecycleStageStatusKey;
  /**
   * @displayName Workspace ID
   * @validationRule Required for create/update operations
   */
  workspaceID: Pick<Workspace, 'id' | 'workspaceName'>;
}

export const _LifecycleStage = 'LifecycleStage' as const;